   "template": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>The rings of AwwO</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;600&family=Space+Grotesk:wght@500;700&family=JetBrains+Mono:wght@400&display=block\">\n<script type=\"importmap\">{\"imports\":{\"three\":\"https://cdn.jsdelivr.net/npm/three@0.186.1/build/three.module.js\",\"three/addons/\":\"https://cdn.jsdelivr.net/npm/three@0.186.1/examples/jsm/\"}}</script>\n<style>html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#05070c}#film,#overlay{position:fixed;inset:0;width:100%;height:100%;display:block}#overlay{pointer-events:none}#play{position:fixed;left:14px;bottom:14px;z-index:2;font:600 13px/1 system-ui,sans-serif;padding:8px 12px;border-radius:6px;border:1px solid rgba(255,255,255,.35);background:rgba(0,0,0,.45);color:#fff;cursor:pointer}html[data-rendering] #play{display:none}</style>\n</head>\n<body>\n<canvas id=\"film\"></canvas>\n<canvas id=\"overlay\"></canvas>\n<button id=\"play\" type=\"button\">Play</button>\n<script>window.FILM_SHEET = {{in:from_director_sheet}};</script>\n<script>window.FILM_DATA = {{in:data}};</script>\n<script type=\"module\">{{in:from_kernel}}</script>\n<script type=\"module\">{{in:from_terrain}}</script>\n<script type=\"module\">{{in:from_city}}</script>\n<script type=\"module\">{{in:from_rings}}</script>\n<script type=\"module\">{{in:from_captions}}</script>\n<script type=\"module\">{{in:from_camera}}</script>\n<script type=\"module\">{{in:from_sound}}</script>\n<script type=\"module\">F.boot();</script>\n</body>\n</html>\n",
